alter table public.products add column if not exists old_price numeric; alter table public.products add column if not exists image_url text; alter table public.products add column if not exists whatsapp_number text; alter table public.products add column if not exists whatsapp_message text; alter table public.products add column if not exists share_count integer not null default 0; update public.products set old_price=compare_price where old_price is null and compare_price is not null;
alter table public.stores add column if not exists referral_code text unique;
create table if not exists public.referral_codes(id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete cascade,code text not null unique,active boolean not null default true,clicks integer not null default 0,signups integer not null default 0,rewards numeric not null default 0,created_at timestamptz not null default now());
create table if not exists public.referrals(id uuid primary key default gen_random_uuid(),referrer_store_id uuid not null references public.stores(id) on delete cascade,code_id uuid references public.referral_codes(id) on delete set null,referred_store_id uuid references public.stores(id) on delete set null,referred_email text,reward numeric not null default 0,status text not null default 'pending',created_at timestamptz not null default now(),converted_at timestamptz);
create index if not exists referral_codes_store_idx on public.referral_codes(store_id); create index if not exists referrals_referrer_idx on public.referrals(referrer_store_id);
alter table public.referral_codes enable row level security; alter table public.referrals enable row level security;
drop policy if exists referral_codes_access on public.referral_codes; create policy referral_codes_access on public.referral_codes for all to authenticated using (is_super_admin() or is_store_member(store_id)) with check (is_super_admin() or is_store_manager(store_id));
drop policy if exists referrals_access on public.referrals; create policy referrals_access on public.referrals for all to authenticated using (is_super_admin() or is_store_member(referrer_store_id) or is_store_member(referred_store_id)) with check (is_super_admin() or is_store_manager(referrer_store_id));
create or replace function public.track_referral_click(p_code text) returns void language plpgsql security definer set search_path=public as $$ begin update public.referral_codes set clicks=clicks+1 where code=p_code and active=true; end $$;
create or replace function public.register_referral(p_code text,p_email text) returns uuid language plpgsql security definer set search_path=public as $$ declare c public.referral_codes; r uuid; begin select * into c from public.referral_codes where code=p_code and active=true limit 1; if c.id is null then return null; end if; insert into public.referrals(referrer_store_id,code_id,referred_email,status) values(c.store_id,c.id,lower(trim(p_email)),'pending') returning id into r; update public.referral_codes set signups=signups+1 where id=c.id; return r; end $$;
revoke all on function public.track_referral_click(text) from public; grant execute on function public.track_referral_click(text) to anon,authenticated;
revoke all on function public.register_referral(text,text) from public; grant execute on function public.register_referral(text,text) to authenticated;